import { Dialog, type DialogCloseDetail } from '@absoluteui/components/dialog';

const confirm = Dialog.create({
  title: 'Delete project?',
  description: 'This permanently removes the project.',
  role: 'alertdialog',
  actions: [
    { label: 'Cancel', value: 'cancel', autofocus: true },
    { label: 'Delete', value: 'delete', variant: 'danger' },
  ],
});
confirm.element.addEventListener('aui-close', (event) => {
  const { returnValue } = (event as CustomEvent<DialogCloseDetail>).detail;
  if (returnValue === 'delete') {
    // perform deletion
  }
});
confirm.open();

import { Dialog } from '@absoluteui/components/dialog';

let dirty = true;
const editor = Dialog.create({ title: 'Edit profile', closeOnBackdrop: true });
editor.element.addEventListener('aui-cancel', (event) => {
  if (dirty) event.preventDefault();
});
editor.open();
dirty = false;
